import os
import tomllib
from typing import Any


class EnvCfgError(Exception):
    pass


def _coerce(value: str, target: type) -> Any:
    if target is int:
        return int(value)
    if target is float:
        return float(value)
    if target is bool:
        lower = value.lower()
        if lower in ("true", "yes", "1"):
            return True
        if lower in ("false", "no", "0"):
            return False
        raise EnvCfgError(f"bool: expected true/false/yes/no/1/0, got '{value}'")
    if target is str:
        return value
    raise EnvCfgError(f"type: expected {target.__name__}, got '{value}'")


def load(
    defaults: dict[str, Any],
    toml_path: str | None = None,
    prefix: str = "APP",
    env: dict[str, str] | None = None,
) -> dict[str, Any]:
    if env is None:
        env = dict(os.environ)

    cfg = dict(defaults)

    if toml_path is not None:
        try:
            with open(toml_path, "rb") as f:
                toml = tomllib.load(f)
            cfg.update(toml)
        except FileNotFoundError:
            pass

    for key, value in env.items():
        if not key.startswith(prefix + "__"):
            continue
        path = key[len(prefix) + 2 :].lower().split("__")
        if path[0] not in cfg:
            raise EnvCfgError(f"{key}: no default for this configuration option")
        target = cfg[path[0]]
        if isinstance(target, dict):
            for seg in path[1:]:
                if seg not in target:
                    target[seg] = {}
                target = target[seg]
        else:
            cfg[path[0]] = _coerce(value, type(target))

    return cfg

import os
import tempfile
import pytest
from envcfg import load, EnvCfgError


def _toml(path: str, data: dict) -> None:
    with open(path, "w") as f:
        f.write("[a]\n")
        for k, v in data.items():
            f.write(f"  {k} = {v}\n")


def _env(prefix: str, mapping: dict[str, str]) -> None:
    for k, v in mapping.items():
        os.environ[f"{prefix}__{k.upper()}"] = v


def _clear_env(prefix: str) -> None:
    for k in list(os.environ.keys()):
        if k.startswith(prefix + "__"):
            del os.environ[k]


def test_envcfg_error_type():
    with pytest.raises(EnvCfgError):
        load({"a": 1}, env={"APP__A": "bad"})


def test_defaults_only():
    cfg = load({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_over_defaults():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        path = f.name
    try:
        _toml(path, {"a": 10, "c": 3})
        cfg = load({"a": 1, "b": 2}, toml_path=path)
        assert cfg == {"a": 10, "b": 2, "c": 3}
    finally:
        os.unlink(path)


def test_missing_toml_ignored():
    cfg = load({"a": 1}, toml_path="/nonexistent.toml")
    assert cfg == {"a": 1}


def test_env_over_toml():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        path = f.name
    try:
        _toml(path, {"a": 1, "b": 2})
        _env("APP", {"a": "100"})
        cfg = load({"a": 1, "b": 2}, toml_path=path)
        assert cfg == {"a": 100, "b": 2}
    finally:
        os.unlink(path)


def test_env_over_defaults():
    _env("APP", {"a": "100"})
    cfg = load({"a": 1, "b": 2})
    assert cfg == {"a": 100, "b": 2}


def test_nested_defaults():
    cfg = load({"server": {"port": 8080, "host": "localhost"}})
    assert cfg == {"server": {"port": 8080, "host": "localhost"}}


